/**
 * Monday.com Node - Version 2
 * Discriminator: resource=item, operation=getBulkImportStatus
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Check an asynchronous bulk import job by its job ID, optionally with the per-row report */
export type MondayComV2ItemGetBulkImportStatusParams = {
  resource: 'item';
  operation: 'getBulkImportStatus';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The job ID returned by a Bulk Import run. Poll every 10 seconds. Note: if the import report is ready, the report URL expires after 10 minutes.
 */
    bulkImportJobId: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    bulkImportStatusOptions?: {
    /** Whether to also output one item per imported row from monday's import report (serial number, status, item ID, error), when the report is ready
     * @default false
     */
    includeRowResults?: boolean | Expression<boolean>;
  };
};

export type MondayComV2ItemGetBulkImportStatusNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2ItemGetBulkImportStatusParams> & { credentials?: Credentials };
};